// pydantic JSON Schema → zod 生成器（铁纪律：zod 禁止手抄，必须由本脚本生成）
// 用法: cd backend/ts-worker && node scripts/generate-zod.mjs
import fs from 'node:fs';
import path from 'node:path';
import { jsonSchemaToZod } from 'json-schema-to-zod';

const here = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const src = path.join(here, '..', '..', 'ts-migration', 'schemas', 'pydantic-schemas.json');
const schemas = JSON.parse(fs.readFileSync(src, 'utf8'));
const out = [
  '// AUTO-GENERATED by scripts/generate-zod.mjs — DO NOT EDIT BY HAND.',
  '// 源: backend/ts-migration/schemas/pydantic-schemas.json（Python pydantic 模型导出）',
  "import { z } from 'zod';",
  '',
];
let ok = 0, fail = 0;
for (const [key, schema] of Object.entries(schemas)) {
  // 用「模块_类名」保证唯一（不同模块同名模型如 ShipmentCreate 会撞名）
  const name = key.replace(/[^A-Za-z0-9_]/g, '_');
  try {
    const raw = jsonSchemaToZod(schema, { module: 'esm', name });
    // 去掉每个 schema 自带的 import/export 行：只保留顶层单次 import z
    const zod = String(raw)
      .split('\n')
      .filter((line) => !/^\s*import\s/.test(line) && !/^\s*export default/.test(line))
      .join('\n')
      .trim();
    out.push('// ' + key);
    out.push(zod);
    ok++;
  } catch (e) {
    out.push('// ' + key + ': GENERATION FAILED (' + String(e).slice(0, 100) + ')');
    fail++;
  }
}
const dest = path.join(here, '..', 'src', 'generated', 'schemas.ts');
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.writeFileSync(dest, out.join('\n') + '\n', 'utf8');
console.log('generated:', dest, '| ok:', ok, '| fail:', fail);